import itertools
base = ['secret', 'password', 'john', 'archive', '7z', 'file', 'word', 'text', 'found', 'solution', 'answer', 'key', 'passphrase', 'secret_file', 'secretfile', 'secret.txt', 'secret_file.txt']
leet_map = {'a':'@','e':'3','i':'1','o':'0','s':'$','t':'7'}
def leetify(word):
    res = set()
    # generate all combinations of substitutions
    positions = [i for i,ch in enumerate(word) if ch.lower() in leet_map]
    for mask in range(1 << len(positions)):
        w = list(word)
        for idx, pos in enumerate(positions):
            if mask & (1 << idx):
                w[pos] = leet_map[word[pos].lower()]
        res.add(''.join(w))
    return res
candidates = set()
for b in base:
    candidates.add(b)
    candidates.add(b.upper())
    candidates.add(b.capitalize())
    candidates.add(b[::-1])  # reverse
    for l in leetify(b):
        candidates.add(l)
    # add numbers
    for i in range(10):
        candidates.add(b + str(i))
        candidates.add(b + str(i) + str(i))
        candidates.add(str(i) + b)
    for suffix in ['123', '456', '789', '000', '!', '@', '#', '$', '%', '&', '*', '?']:
        candidates.add(b + suffix)
with open('leet.txt', 'w') as f:
    for c in candidates:
        if len(c) <= 28:
            f.write(c + '\n')
print(f'Generated {len(candidates)} candidates')
EOF

